function validate([root, distance]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 1024) return 'The tree has at most 1024 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each node value is a whole number from 1 to 100.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  if (!Number.isInteger(distance) || distance < 1 || distance > 10) return 'distance is a whole number from 1 to 10.';
  return null;
}

