function countPairs(root, distance) {
  let pairs = 0;

  const dfs = (node) => {
    const counts = new Array(distance + 1).fill(0);
    if (!node) {
      return counts;
    }
    if (!node.left && !node.right) {
      counts[1] = 1;
      return counts;
    }
    const left = dfs(node.left);
    const right = dfs(node.right);
    for (let i = 1; i <= distance; i++) {
      for (let j = 1; i + j <= distance; j++) {
        pairs += left[i] * right[j];
      }
    }
    for (let d = 1; d < distance; d++) {
      counts[d + 1] = left[d] + right[d];
    }
    return counts;
  };

  dfs(root);
  return pairs;
}

