function countPairs(root, distance) {
  // Build an undirected graph of the tree, then walk breadth first from every leaf.
  const nodes = [root];
  const adjacent = [[]];
  const leaves = [];
  for (let k = 0; k < nodes.length; k++) {
    const kids = [nodes[k].left, nodes[k].right].filter(Boolean);
    if (kids.length === 0) leaves.push(k);
    for (const kid of kids) {
      adjacent.push([k]);
      adjacent[k].push(nodes.length);
      nodes.push(kid);
    }
  }
  const isLeaf = new Set(leaves);
  let ordered = 0;
  for (const start of leaves) {
    const dist = new Map([[start, 0]]);
    const queue = [start];
    for (let q = 0; q < queue.length; q++) {
      const at = queue[q];
      if (at !== start && isLeaf.has(at) && dist.get(at) <= distance) ordered++;
      for (const next of adjacent[at]) if (!dist.has(next)) { dist.set(next, dist.get(at) + 1); queue.push(next); }
    }
  }
  return ordered / 2;
}

